CompositionLocalProvider(LocalConfiguration provides configuration) {
    MonarchMiniMonth(
        selection = day,
        onSelectionChange = { day = it },
        previousMonthIcon = { MonarchIcon(SampleIcons.ChevronLeft, null) },
        nextMonthIcon = { MonarchIcon(SampleIcons.ChevronRight, null) },
        today = {{today|millis}},
        dayInfo = { date ->
            when (date) {
                {{events.0.date|millis}} -> MonarchMiniMonthDayInfo(dots = listOf({{events.0.dots.0|tone}}), description = {{events.0.description}})
                {{events.1.date|millis}} -> MonarchMiniMonthDayInfo(dots = listOf({{events.1.dots.0|tone}}, {{events.1.dots.1|tone}}), description = {{events.1.description}})
                {{events.2.date|millis}} -> MonarchMiniMonthDayInfo(dots = listOf({{events.2.dots.0|tone}}), description = {{events.2.description}})
                {{events.3.date|millis}} -> MonarchMiniMonthDayInfo(dots = listOf({{events.3.dots.0|tone}}, {{events.3.dots.1|tone}}, {{events.3.dots.2|tone}}), description = {{events.3.description}})
                else -> null
            }
        },
    )
}

