examples.code:
CompositionLocalProvider(LocalConfiguration provides configuration) {
    MonarchMiniMonth(
        selection = day,
        onSelectionChange = { day = it },
        previousMonthIcon = { MonarchIcon(SampleIcons.ChevronLeft, null) },
        nextMonthIcon = { MonarchIcon(SampleIcons.ChevronRight, null) },
        today = 1_793_750_400_000L,
        dayInfo = { date ->
            when (date) {
                1_793_836_800_000L -> MonarchMiniMonthDayInfo(dots = listOf(MonarchTone.Accent), description = "1 event")
                1_794_268_800_000L -> MonarchMiniMonthDayInfo(dots = listOf(MonarchTone.Accent, MonarchTone.Info), description = "2 events")
                1_794_960_000_000L -> MonarchMiniMonthDayInfo(dots = listOf(MonarchTone.Warning), description = "Deadline")
                1_795_478_400_000L -> MonarchMiniMonthDayInfo(dots = listOf(MonarchTone.Accent, MonarchTone.Success, MonarchTone.Danger), description = "3 events")
                else -> null
            }
        },
    )
}

MonarchMiniMonth(
    selection = day,
    onSelectionChange = { day = it },
    previousMonthIcon = {
        MonarchIcon(SampleIcons.ChevronLeft, null)
    },
    nextMonthIcon = {
        MonarchIcon(SampleIcons.ChevronRight, null)
    },
    minimumDate = now,
    maximumDate = now + 30 * 86_400_000L,
    isDateDisabled = { date ->
        val weekday = Calendar.getInstance(TimeZone.getTimeZone("UTC")).apply { timeInMillis = date }
            .get(Calendar.DAY_OF_WEEK)
        weekday == Calendar.SATURDAY || weekday == Calendar.SUNDAY
    },
)
